enum class Command{start,pause,resume,stop};
struct ReplayEntry{fs::path path;erplay::Summary summary;std::uintmax_t bytes;fs::file_time_type modified;};
struct Snapshot{bool connected{},player{};erplay::RecordingState state{erplay::RecordingState::idle};std::uint64_t samples{},dropped{},reconnects{},bytes{},active_ns{};double rate{},latency_ms{};std::vector<ReplayEntry> replays;std::wstring error;};
struct App{HWND window{},connection{},player{},recording{},stats{},button_start{},button_pause{},button_resume{},button_stop{},button_folder{},list{};HWND replay_state{},replay_meta{},replay_values{},timeline{},speed{},preview{},bookmarks{},button_open{},button_delete{},button_rename{},button_play{},button_rpause{},button_rstop{},button_restart{},button_step_back{},button_step_forward{},button_bookmark_add{},button_bookmark_delete{},button_trail{},button_reset{},trail_length{};HWND probe_state{},button_probe{},button_probe_stop{};game_control::Client control;std::atomic<DWORD> game_pid{};std::wstring probe_text;bool stop_hotkey{};HFONT font{};fs::path root,replays,logs;std::mutex mutex,commands_mutex;Snapshot data;std::queue<Command> commands;std::atomic_bool stopping{};std::jthread worker;std::ofstream log;std::unique_ptr<replay::Player> replay_player;std::vector<std::uint64_t> replay_bookmarks;std::vector<erplay::Vec3> preview_path;fs::path opened_replay;bool show_trail{true},timeline_dragging{};int trail_percent{100};};
App app;

std::uint64_t monotonic_ns(){return GetTickCount64()*1'000'000ULL;}
std::uint64_t unix_ns(){return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::system_clock::now().time_since_epoch()).count());}
fs::path app_root(){wchar_t b[32768]{};DWORD n=GetEnvironmentVariableW(L"LOCALAPPDATA",b,32768);return (n&&n<32768?fs::path(b):fs::temp_directory_path())/L"EldenRingTheaterMode";}
std::wstring time_text(std::uint64_t ns){auto ms=ns/1'000'000ULL;std::wostringstream o;o<<std::setfill(L'0')<<std::setw(2)<<(ms/3'600'000ULL)<<L":"<<std::setw(2)<<((ms/60'000ULL)%60)<<L":"<<std::setw(2)<<((ms/1000ULL)%60)<<L"."<<std::setw(3)<<(ms%1000);return o.str();}
std::wstring file_stem(){std::time_t now=std::time(nullptr);std::tm t{};localtime_s(&t,&now);std::wostringstream s;s<<L"replay_"<<std::put_time(&t,L"%Y-%m-%d_%H%M%S");return s.str();}
void log_line(const std::string&s){std::lock_guard lock(app.mutex);if(app.log)app.log<<s<<"\n"<<std::flush;}
void post_command(Command c){{std::lock_guard lock(app.commands_mutex);app.commands.push(c);}PostMessageW(app.window,WM_REFRESH,0,0);}
bool read_message(HANDLE h,WireMessage&m){char*p=reinterpret_cast<char*>(&m);std::size_t left=sizeof(m);while(left&&!app.stopping.load()){DWORD n=0;if(!ReadFile(h,p,static_cast<DWORD>(left),&n,nullptr)||!n)return false;p+=n;left-=n;}return left==0;}
std::vector<ReplayEntry> scan_replays(){std::vector<ReplayEntry> out;std::error_code ec;for(const auto&it:fs::directory_iterator(app.replays,ec)){if(ec)break;if(!it.is_regular_file()||it.path().extension()!=L".erplay")continue;try{out.push_back({it.path(),erplay::validate(it.path()),it.file_size(),it.last_write_time()});}catch(const std::exception&e){log_line(std::string("Replay validation failed: ")+e.what());}}std::sort(out.begin(),out.end(),[](const auto&a,const auto&b){return a.modified>b.modified;});return out;}
void set_data(const Snapshot&s){std::lock_guard lock(app.mutex);app.data=s;}
void update_ui();
std::queue<Command> take_commands(){std::lock_guard lock(app.commands_mutex);std::queue<Command> q;std::swap(q,app.commands);return q;}
void refresh_window(){PostMessageW(app.window,WM_REFRESH,0,0);}
void update_probe_ui(){if(!app.probe_state)return;const auto s=app.control.state();const wchar_t* phases[]={L"OFF",L"ARMED",L"OBSERVING (no repeated writes)",L"OFF (COMPLETE)",L"OFF (ERROR)"};std::wostringstream text;text<<L"Phase 4A write probe: "<<phases[std::min(s.phase,4u)];if(!s.connected)text<<L" | "<<s.diagnostic;else text<<L" | Control IPC: CONNECTED | Runtime: "<<(s.ready?L"READY":L"WAITING");if(!app.stop_hotkey)text<<L" | F6 unavailable: close other hosts and relaunch";if(s.detail)text<<L" | error="<<s.detail;if(text.str()!=app.probe_text){app.probe_text=text.str();SetWindowTextW(app.probe_state,app.probe_text.c_str());}EnableWindow(app.button_probe,app.stop_hotkey&&s.connected&&s.ready&&!s.pending&&s.phase!=game_control::armed&&s.phase!=game_control::observing);}
void emergency_stop(){app.control.emergency_stop();if(app.replay_player)app.replay_player->stop();post_command(Command::stop);log_line("Emergency STOP requested: probe OFF, offline ReplayPlayer stopped, recorder stop requested");}
void start_probe(){if(app.stop_hotkey&&app.control.nudge()){log_line("Explicit PROBE_NUDGE requested: +0.5 X, one write only");update_probe_ui();}else log_line("PROBE_NUDGE refused: control/runtime not ready or probe busy");}
void save_bookmarks(){if(app.opened_replay.empty())return;auto path=app.opened_replay;path+=L".bookmarks";try{replay::BookmarkStore store(path);for(auto t:app.replay_bookmarks)store.add(t);store.save();}catch(const std::exception&e){log_line(std::string("Bookmark save failed: ")+e.what());}}
void load_bookmarks(){app.replay_bookmarks.clear();auto path=app.opened_replay;path+=L".bookmarks";try{replay::BookmarkStore store(path);store.load();app.replay_bookmarks=store.timestamps();}catch(const std::exception&e){log_line(std::string("Bookmark load failed: ")+e.what());}}
void update_replay_panel(){if(!app.replay_player){SetWindowTextW(app.replay_state,L"Replay: STOPPED — open a validated .erplay file");SetWindowTextW(app.replay_meta,L"No replay loaded");SetWindowTextW(app.replay_values,L"Position: —\r\nOrientation XYZW: —");return;}auto&p=*app.replay_player;const auto&s=p.state();const wchar_t* names[]={L"STOPPED",L"LOADING",L"READY",L"PLAYING",L"PAUSED",L"SEEKING",L"ERROR"};const auto&sum=p.summary();std::wostringstream meta;meta<<L"REPLAY LOADED     Game: Elden Ring 1.17     Duration: "<<time_text(sum.duration_ns)<<L"     Samples: "<<sum.sample_count<<L"     Rate: "<<std::fixed<<std::setprecision(2)<<sum.actual_rate_hz<<L" Hz     Chunks: "<<sum.chunk_count;SetWindowTextW(app.replay_meta,meta.str().c_str());std::wostringstream st;st<<L"Replay: "<<names[static_cast<int>(s.status)]<<L"     "<<time_text(s.timestamp_ns)<<L" / "<<time_text(sum.duration_ns)<<L"     Sample: "<<(s.sample_index+1)<<L" / "<<sum.sample_count<<L"     Speed: "<<s.speed<<L"x";SetWindowTextW(app.replay_state,st.str().c_str());std::wostringstream values;values<<std::fixed<<std::setprecision(3)<<L"Position: X "<<s.position.x<<L"   Y "<<s.position.y<<L"   Z "<<s.position.z<<L"\r\nOrientation XYZW: "<<std::setprecision(5)<<s.orientation.x<<L"   "<<s.orientation.y<<L"   "<<s.orientation.z<<L"   "<<s.orientation.w;SetWindowTextW(app.replay_values,values.str().c_str());if(!app.timeline_dragging){const auto d=sum.duration_ns;const int pos=d?static_cast<int>((static_cast<long double>(s.timestamp_ns)*10000.0L)/d):0;SendMessageW(app.timeline,TBM_SETPOS,TRUE,std::clamp(pos,0,10000));}SendMessageW(app.bookmarks,LB_RESETCONTENT,0,0);for(auto t:app.replay_bookmarks){auto item=time_text(t);SendMessageW(app.bookmarks,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(item.c_str()));}InvalidateRect(app.preview,nullptr,FALSE);}
void build_preview_path(){app.preview_path.clear();if(!app.replay_player)return;const auto n=app.replay_player->summary().sample_count;const auto stride=std::max<std::uint64_t>(1,(n+2999)/3000);for(std::uint64_t i=0;i<n;i+=stride){const auto s=app.replay_player->reader().sample(i);app.preview_path.push_back(s.position);}if(n&&((n-1)%stride)!=0)app.preview_path.push_back(app.replay_player->reader().sample(n-1).position);}
void open_selected_replay(){const auto n=static_cast<int>(SendMessageW(app.list,LB_GETCURSEL,0,0));if(n==LB_ERR)return;Snapshot s;{std::lock_guard lock(app.mutex);s=app.data;}if(static_cast<std::size_t>(n)>=s.replays.size())return;try{auto next=std::make_unique<replay::Player>(s.replays[static_cast<std::size_t>(n)].path);app.opened_replay=s.replays[static_cast<std::size_t>(n)].path;app.replay_player=std::move(next);build_preview_path();load_bookmarks();update_replay_panel();}catch(const std::exception&e){const auto w=std::wstring(e.what(),e.what()+std::strlen(e.what()));MessageBoxW(app.window,w.c_str(),L"INCOMPATIBLE REPLAY / LOAD ERROR",MB_ICONERROR|MB_OK);}}
void bookmark_add(){if(!app.replay_player)return;app.replay_bookmarks.push_back(app.replay_player->state().timestamp_ns);std::sort(app.replay_bookmarks.begin(),app.replay_bookmarks.end());app.replay_bookmarks.erase(std::unique(app.replay_bookmarks.begin(),app.replay_bookmarks.end()),app.replay_bookmarks.end());save_bookmarks();update_replay_panel();}
void bookmark_delete(){const auto i=static_cast<int>(SendMessageW(app.bookmarks,LB_GETCURSEL,0,0));if(i==LB_ERR||static_cast<std::size_t>(i)>=app.replay_bookmarks.size())return;app.replay_bookmarks.erase(app.replay_bookmarks.begin()+i);save_bookmarks();update_replay_panel();}
void rename_selected_replay(){const auto n=static_cast<int>(SendMessageW(app.list,LB_GETCURSEL,0,0));if(n==LB_ERR)return;Snapshot s;{std::lock_guard lock(app.mutex);s=app.data;}if(static_cast<std::size_t>(n)>=s.replays.size())return;const auto old=s.replays[static_cast<std::size_t>(n)].path;wchar_t name[32768]{};wcsncpy_s(name,old.c_str(),_TRUNCATE);OPENFILENAMEW ofn{sizeof(ofn)};ofn.hwndOwner=app.window;ofn.lpstrFilter=L"Elden Ring replay (*.erplay)\0*.erplay\0All files (*.*)\0*.*\0";ofn.lpstrFile=name;ofn.nMaxFile=32768;ofn.lpstrDefExt=L"erplay";ofn.Flags=OFN_PATHMUSTEXIST|OFN_NOCHANGEDIR|OFN_OVERWRITEPROMPT;if(!GetSaveFileNameW(&ofn))return;fs::path dest=name;if(dest.parent_path()!=old.parent_path()||dest.extension()!=L".erplay"){MessageBoxW(app.window,L"Choose a new .erplay filename in the same replay folder.",L"Rename replay",MB_ICONWARNING|MB_OK);return;}try{fs::rename(old,dest);auto ob=old;ob+=L".bookmarks";auto nb=dest;nb+=L".bookmarks";if(fs::exists(ob))fs::rename(ob,nb);app.opened_replay.clear();app.replay_player.reset();app.replay_bookmarks.clear();auto files=scan_replays();{std::lock_guard lock(app.mutex);app.data.replays=std::move(files);}update_ui();update_replay_panel();}catch(const std::exception&e){MessageBoxA(app.window,e.what(),"Rename failed",MB_ICONERROR|MB_OK);}}
void delete_selected_replay(){const auto n=static_cast<int>(SendMessageW(app.list,LB_GETCURSEL,0,0));if(n==LB_ERR)return;Snapshot s;{std::lock_guard lock(app.mutex);s=app.data;}if(static_cast<std::size_t>(n)>=s.replays.size())return;const auto path=s.replays[static_cast<std::size_t>(n)].path;if(MessageBoxW(app.window,(L"Permanently delete "+path.filename().wstring()+L"? This cannot be undone.").c_str(),L"Delete replay",MB_YESNO|MB_ICONWARNING)!=IDYES)return;std::error_code ec;fs::remove(path,ec);auto bm=path;bm+=L".bookmarks";fs::remove(bm,ec);if(app.opened_replay==path){app.opened_replay.clear();app.replay_player.reset();app.replay_bookmarks.clear();update_replay_panel();}auto files=scan_replays();{std::lock_guard lock(app.mutex);app.data.replays=std::move(files);}PostMessageW(app.window,WM_REFRESH,0,0);}

void pipe_worker(){
    fs::path log_path=app.logs/L"TheaterModeRecorder.log";{std::lock_guard lock(app.mutex);if(!app.log.is_open())app.log.open(log_path,std::ios::binary|std::ios::app);}
    std::unique_ptr<erplay::Writer> writer;std::unique_ptr<erplay::RecordingSession> session;Snapshot snap;std::uint64_t last_seq=0,last_source=0,first_source=0,window_start=GetTickCount64(),window_samples=0,latency_count=0;double latency_sum=0;
    auto update_state=[&]{set_data(snap);refresh_window();};
    auto stop_recording=[&]{if(session&&(snap.state==erplay::RecordingState::recording||snap.state==erplay::RecordingState::paused)){snap.state=erplay::RecordingState::saving;update_state();try{auto result=session->stop();snap.state=erplay::RecordingState::ready;snap.samples=result.sample_count;snap.active_ns=result.duration_ns;snap.bytes=0;snap.replays=scan_replays();if(!snap.replays.empty())snap.bytes=snap.replays.front().bytes;log_line("Recording finalized samples="+std::to_string(result.sample_count)+" duration_ns="+std::to_string(result.duration_ns)+" actual_hz="+std::to_string(result.actual_rate_hz)+" chunks="+std::to_string(result.chunk_count));}catch(const std::exception&e){snap.state=erplay::RecordingState::error;snap.error=std::wstring(e.what(),e.what()+std::strlen(e.what()));log_line(std::string("Finalization failed: ")+e.what());}session.reset();writer.reset();update_state();}};
    for(const auto&it:fs::directory_iterator(app.replays)){if(!it.is_regular_file()||!it.path().filename().wstring().ends_with(L".erplay.tmp"))continue;auto name=it.path();name.replace_extension();if(fs::exists(name)){auto recovered=name;recovered.replace_extension(L".recovered.erplay");name=recovered;}try{auto r=erplay::recover_incomplete(it.path(),name);log_line("Recovered interrupted recording: "+name.string()+" samples="+std::to_string(r.sample_count));}catch(const std::exception&e){log_line(std::string("Incomplete replay recovery failed: ")+e.what());}}
    snap.replays=scan_replays();update_state();
    const wchar_t* pipe_name=L"\\\\.\\pipe\\EldenRingTheaterMode_1_17";
    while(!app.stopping.load()){
        HANDLE pipe=CreateNamedPipeW(pipe_name,PIPE_ACCESS_INBOUND,PIPE_TYPE_BYTE|PIPE_READMODE_BYTE|PIPE_WAIT,1,sizeof(WireMessage),sizeof(WireMessage),0,nullptr);
        if(pipe==INVALID_HANDLE_VALUE){snap.error=L"Could not create named pipe";update_state();break;}
        if(!ConnectNamedPipe(pipe,nullptr)&&GetLastError()!=ERROR_PIPE_CONNECTED){CloseHandle(pipe);continue;}
        DWORD sample_pid=0;GetNamedPipeClientProcessId(pipe,&sample_pid);app.game_pid.store(sample_pid);snap.connected=true;if(last_seq)++snap.reconnects;log_line("IPC connected");update_state();
        while(!app.stopping.load()){
            WireMessage m{};if(!read_message(pipe,m))break;if(m.magic!=MAGIC||m.version!=1)continue;
            if(m.kind==4)continue;if(m.kind==5){snap.error=L"Game module rejected runtime profile";update_state();continue;}if(m.kind==1)continue;if(m.kind!=2&&m.kind!=3)continue;
            snap.player=m.kind==2&&m.player_present!=0;
            if(last_seq&&m.sequence>last_seq+1)snap.dropped+=m.sequence-last_seq-1;
            if(last_seq&&m.sequence<=last_seq)log_line("Duplicate/regressing IPC sequence");last_seq=m.sequence;
            if(last_source&&m.timestamp_ns<last_source){log_line("Player timestamp regression; sample skipped");update_state();continue;}
            last_source=m.timestamp_ns;++window_samples;
            const auto now_ns=monotonic_ns();if(now_ns>=m.timestamp_ns){latency_sum+=double(now_ns-m.timestamp_ns)/1e6;++latency_count;snap.latency_ms=latency_sum/latency_count;}
            auto pending_commands=take_commands();while(!pending_commands.empty()){auto c=pending_commands.front();pending_commands.pop();
                try{
                    if(c==Command::start&&(snap.state!=erplay::RecordingState::recording&&snap.state!=erplay::RecordingState::paused)&&snap.player){
                        erplay::Metadata md;md.game_version="2.7.0.0";md.recording_start_unix_ns=unix_ns();md.requested_rate_hz=60.0;md.title="Elden Ring recording";auto stem=file_stem();auto final=app.replays/(stem+L".erplay");for(unsigned i=1;fs::exists(final);++i)final=app.replays/(stem+L"_"+std::to_wstring(i)+L".erplay");writer=std::make_unique<erplay::Writer>(final,std::move(md),600);session=std::make_unique<erplay::RecordingSession>(*writer);session->start();snap.state=erplay::RecordingState::recording;snap.samples=0;snap.bytes=0;snap.active_ns=0;first_source=0;log_line("Recording started: "+final.string());
                    }else if(c==Command::pause&&session&&snap.state==erplay::RecordingState::recording){session->pause(monotonic_ns());snap.state=erplay::RecordingState::paused;log_line("Recording paused");}
                    else if(c==Command::resume&&session&&snap.state==erplay::RecordingState::paused){session->resume(monotonic_ns());snap.state=erplay::RecordingState::recording;log_line("Recording resumed");}
                    else if(c==Command::stop)stop_recording();
                }catch(const std::exception&e){snap.state=erplay::RecordingState::error;log_line(std::string("Recorder command failed: ")+e.what());}
            }
            if(snap.player&&snap.state==erplay::RecordingState::recording){try{erplay::Sample s;s.source_time_ns=m.timestamp_ns;s.position={m.position[0],m.position[1],m.position[2]};s.orientation={m.quaternion_xyzw[0],m.quaternion_xyzw[1],m.quaternion_xyzw[2],m.quaternion_xyzw[3]};if(!first_source)first_source=m.timestamp_ns;session->ingest(s);snap.samples=session->accepted_samples();snap.active_ns=m.timestamp_ns-first_source-session->paused_duration_ns();std::error_code ec;snap.bytes=fs::file_size(writer->temporary_path(),ec);if(ec)snap.bytes=0;}catch(const std::exception&e){snap.state=erplay::RecordingState::error;log_line(std::string("Sample rejected: ")+e.what());}}
            const auto now=GetTickCount64();if(now-window_start>=1000){snap.rate=double(window_samples)*1000.0/double(now-window_start);window_samples=0;window_start=now;update_state();}
        }
        app.game_pid.store(0);DisconnectNamedPipe(pipe);CloseHandle(pipe);snap.connected=false;snap.player=false;log_line("IPC disconnected");update_state();
    }
    stop_recording();
}

void create_control(HWND parent,HWND&h,const wchar_t*text,DWORD style,int id){h=CreateWindowExW(0,L"BUTTON",text,WS_CHILD|WS_VISIBLE|style,0,0,0,0,parent,reinterpret_cast<HMENU>(static_cast<INT_PTR>(id)),GetModuleHandleW(nullptr),nullptr);SendMessageW(h,WM_SETFONT,reinterpret_cast<WPARAM>(app.font),TRUE);}
