void update_ui(){Snapshot s;{std::lock_guard lock(app.mutex);s=app.data;}SetWindowTextW(app.connection,s.connected?L"Connection: CONNECTED  |  Game: Elden Ring 1.17":L"Connection: WAITING FOR GAME MODULE");SetWindowTextW(app.player,s.player?L"Player: FOUND":L"Player: WAITING");const wchar_t* states[]={L"READY",L"RECORDING",L"PAUSED",L"SAVING...",L"READY",L"ERROR"};SetWindowTextW(app.recording,(std::wstring(L"Recorder: ")+states[static_cast<int>(s.state)]+L"     Duration: "+time_text(s.active_ns)).c_str());std::wostringstream st;st<<L"Samples: "<<s.samples<<L"    Incoming: "<<std::fixed<<std::setprecision(1)<<s.rate<<L" Hz    IPC latency: "<<std::setprecision(2)<<s.latency_ms<<L" ms\r\nData: "<<std::setprecision(3)<<double(s.bytes)/(1024.0*1024.0)<<L" MiB    Dropped samples: "<<s.dropped<<L"    Reconnects: "<<s.reconnects;if(!s.error.empty())st<<L"\r\n"<<s.error;SetWindowTextW(app.stats,st.str().c_str());EnableWindow(app.button_start,s.connected&&s.player&&s.state!=erplay::RecordingState::recording&&s.state!=erplay::RecordingState::paused&&s.state!=erplay::RecordingState::saving);EnableWindow(app.button_pause,s.state==erplay::RecordingState::recording);EnableWindow(app.button_resume,s.state==erplay::RecordingState::paused);EnableWindow(app.button_stop,s.state==erplay::RecordingState::recording||s.state==erplay::RecordingState::paused);SendMessageW(app.list,LB_RESETCONTENT,0,0);for(const auto&e:s.replays){std::wostringstream row;const auto sys_time=std::chrono::system_clock::now()+(e.modified-fs::file_time_type::clock::now());const auto tm=std::chrono::system_clock::to_time_t(sys_time);std::tm date{};localtime_s(&date,&tm);const auto version=std::wstring(e.summary.metadata.game_version.begin(),e.summary.metadata.game_version.end());row<<e.path.filename().wstring()<<L" | "<<time_text(e.summary.duration_ns)<<L" | "<<e.summary.sample_count<<L" samples | "<<std::fixed<<std::setprecision(2)<<double(e.bytes)/(1024.0*1024.0)<<L" MiB | "<<version<<L" | "<<std::put_time(&date,L"%Y-%m-%d %H:%M");SendMessageW(app.list,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(row.str().c_str()));}EnableWindow(app.button_open,!s.replays.empty());EnableWindow(app.button_delete,!s.replays.empty());EnableWindow(app.button_rename,!s.replays.empty());update_replay_panel();}

void create_preview_class(HINSTANCE instance){WNDCLASSW c{};c.lpfnWndProc=[](HWND h,UINT m,WPARAM wp,LPARAM lp)->LRESULT{if(m==WM_ERASEBKGND)return 1;if(m==WM_PAINT){PAINTSTRUCT ps{};HDC dc=BeginPaint(h,&ps);RECT r{};GetClientRect(h,&r);FillRect(dc,&r,static_cast<HBRUSH>(GetStockObject(WHITE_BRUSH)));if(app.replay_player&&!app.preview_path.empty()){double xmin=app.preview_path.front().x,xmax=xmin,zmin=app.preview_path.front().z,zmax=zmin;for(const auto&s:app.preview_path){xmin=std::min(xmin,double(s.x));xmax=std::max(xmax,double(s.x));zmin=std::min(zmin,double(s.z));zmax=std::max(zmax,double(s.z));}const int pad=24,w=std::max(1,int(r.right)-2*pad),hh=std::max(1,int(r.bottom)-2*pad);const double dx=std::max(0.01,xmax-xmin),dz=std::max(0.01,zmax-zmin),scale=std::min(double(w)/dx,double(hh)/dz);auto point=[&](const erplay::Vec3&s){return POINT{pad+int((s.x-(xmin+xmax)/2)*scale+w/2),int(r.bottom)-pad-int((s.z-(zmin+zmax)/2)*scale+hh/2)};};HPEN grid=CreatePen(PS_SOLID,1,RGB(230,234,239)),trail=CreatePen(PS_SOLID,2,RGB(57,120,190));auto old=SelectObject(dc,grid);for(int x=pad;x<int(r.right)-pad;x+=40){MoveToEx(dc,x,pad,nullptr);LineTo(dc,x,int(r.bottom)-pad);}for(int y=pad;y<int(r.bottom)-pad;y+=40){MoveToEx(dc,pad,y,nullptr);LineTo(dc,int(r.right)-pad,y);}if(app.show_trail){SelectObject(dc,trail);const auto total=std::max<std::uint64_t>(1,app.replay_player->summary().sample_count-1);const auto current=std::min<std::size_t>(app.preview_path.size()-1,static_cast<std::size_t>((static_cast<long double>(app.replay_player->state().sample_index)*(app.preview_path.size()-1))/total));const auto span=std::max<std::size_t>(1,app.preview_path.size()*static_cast<std::size_t>(app.trail_percent)/100);const auto begin=current+1>span?current+1-span:0;bool have=false;for(std::size_t i=begin;i<=current;++i){auto p=point(app.preview_path[i]);if(have)LineTo(dc,p.x,p.y);else{MoveToEx(dc,p.x,p.y,nullptr);have=true;}}}SelectObject(dc,old);DeleteObject(grid);DeleteObject(trail);const auto state=app.replay_player->state();const auto q=state.orientation;const auto center=point(state.position);const int rad=7;HBRUSH red=CreateSolidBrush(RGB(205,62,62));auto oldb=SelectObject(dc,red);Ellipse(dc,center.x-rad,center.y-rad,center.x+rad,center.y+rad);SelectObject(dc,oldb);DeleteObject(red);const double fx=2.0*(q.x*q.z+q.w*q.y),fz=1.0-2.0*(q.x*q.x+q.y*q.y);MoveToEx(dc,center.x,center.y,nullptr);LineTo(dc,center.x+int(fx*22),center.y-int(fz*22));SetBkMode(dc,TRANSPARENT);const wchar_t*caption=app.show_trail?L"Player trajectory (X/Z projection)":L"Trail hidden";TextOutW(dc,pad,pad,caption,static_cast<int>(wcslen(caption)));}EndPaint(h,&ps);return 0;}return DefWindowProcW(h,m,wp,lp);};c.hInstance=instance;c.hCursor=LoadCursorW(nullptr,IDC_CROSS);c.hbrBackground=static_cast<HBRUSH>(GetStockObject(WHITE_BRUSH));c.lpszClassName=L"TheaterReplayPreview";RegisterClassW(&c);}

